    columns: int  # Zero means preserve existing column selection.
    center_partial_rows: bool
    cards: tuple[str, ...]  # Direct participants, including intact boundary groups.
    card_labels: tuple[str, ...]
    edges: tuple[tuple[str, str], ...]  # Exact edge IDs and complete source labels.
    reason: str
    evidence_ref: tuple[str, int]


