REPAIRS = tuple(FlowBalanceRepair(*row) for row in _REPAIR_ROWS)
BALANCED_INCLUDES = tuple(dict.fromkeys(repair.include for repair in REPAIRS))


def corpus_flow_balance_profile(include: str) -> dict:
    """Return fresh, source-scoped layout knobs for an exact include identifier."""
    profile = {}
    for repair in REPAIRS:
        if repair.include != include:
            continue
        if repair.columns:
            key = "flow_columns" if repair.mode == "flow" else "columns"
            profile.setdefault(key, {})[repair.container] = repair.columns
        if repair.center_partial_rows:
            profile.setdefault("center_partial_rows", []).append(repair.container)
    return profile
